package org.jlinalg.cli;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.api.io.CleanupMode;
import static org.junit.jupiter.api.Assertions.*;
import static org.jlinalg.cli.GprofilerWorkflowContracts.*;

class PrsiceWorkflowTest {
    @TempDir(cleanup=CleanupMode.NEVER) Path temporary;
    @SuppressWarnings("unchecked") private static Map<String,Object> direct(Object value){return (Map<String,Object>)value;}
    private Map<String,Object> request()throws Exception {
        return PrsiceContracts.validate(map("schema_version",1,"mode","RUN","profile",PrsiceContracts.PROFILE,"operation","SCORE","runtime_home",temporary.resolve("runtime").toString(),"bundle",temporary.toString(),"out",temporary.resolve("new-output").toString(),"inputs",map("base","base.tsv","target_bed","target.bed","target_bim","target.bim","target_fam","target.fam"),"parameters",map("assembly","GRCh37","target_population","declared artificial fixture","reference_population",null,"ignore_fid",false,"id_delimiter","_","base",map("kind","GWAS","effect_scale","BETA","columns",map("snp","SNP","chromosome","CHR","position","BP","a1","A1","a2","A2","effect","BETA","pvalue","P")),"clumping",map("mode","NONE","r2",null,"window_kb",null,"pvalue",null),"filters",map("target",map("maf",0,"missing",1),"reference",null,"base_info",null,"base_maf",null),"alleles",map("palindromic","DROP","strand","EXACT"),"scoring",map("model","add","missing","MEAN_IMPUTE","scale","sum","cumulative",true,"frequency_source","TARGET","thresholds",map("kind","LEVELS","levels",List.of(.01,1))),"phenotype",null,"regression",null,"include_nonfounders",false,"seed",42,"threads",1,"memory_mib",512),"policies",map("unmatched_variants","RETAIN_WITH_WARNING","incomplete_samples","RETAIN_WITH_WARNING","original_warnings","RETAIN_WITH_WARNING","solver_convergence","SOURCE_UNREPORTED_WITH_WARNING","standardization","ORIGINAL_MASK_WITH_WARNING"),"limits",map()));
    }
    @Test void routerDescribesNativeAuditAndUpstreamScope() {var b=new ByteArrayOutputStream();assertEquals(0,JLinAlgCli.run(new String[]{"prsice-tools","--help"},new PrintStream(b),new PrintStream(b)));assertTrue(b.toString().contains("CLUMP"));assertTrue(b.toString().contains("SKIP3"));}
    @Test void unknownScientificChoiceRefused()throws Exception {var q=request();direct(q.get("parameters")).put("silent_strand_repair",true);assertThrows(IOException.class,()->PrsiceContracts.validate(q));}
    @Test void missingScientificChoiceRefused()throws Exception {var q=request();direct(q.get("parameters")).remove("include_nonfounders");assertThrows(IOException.class,()->PrsiceContracts.validate(q));}
    @Test void unusedPhenotypeRefused()throws Exception {var q=request();direct(q.get("inputs")).put("phenotype","phenotype.tsv");assertThrows(IOException.class,()->PrsiceContracts.validate(q));}
    @Test void strandMatchingFollowsSourceBranchOrder(){var a=PrsiceGenotypes.orient("A","G","T","C",false);assertTrue(a.matched());assertTrue(a.complemented());assertFalse(a.flipped());var b=PrsiceGenotypes.orient("A","G","G","A",false);assertTrue(b.flipped());assertFalse(b.complemented());}
    @Test void multibaseAllelesAreNotReverseComplemented(){assertFalse(PrsiceGenotypes.orient("AC","GT","TG","CA",false).matched());assertEquals("AC",PrsiceGenotypes.complement("AC"));}
    @Test void palindromicKeepUsesLiteralDosageOrientation(){var a=PrsiceGenotypes.orient("A","T","T","A",true);assertTrue(a.matched());assertTrue(a.flipped());assertFalse(a.complemented());assertFalse(PrsiceGenotypes.orient("A","T","T","A",false).matched());}
    @Test void asciiFoldDoesNotChangeUnicodeIdentifiersOrAlleles(){assertEquals("Aß",PrsiceTables.asciiUpper("aß"));}
    @Test void sourceParserRejectsJavaNumericExtensionsAndUnderflow(){for(String s:List.of("0x1.0p1","1d","NaN","Inf","1e-400","1e-310"))assertThrows(IOException.class,()->PrsiceTables.finite(s,"fixture"));}
    @Test void sourceParserRetainsQuantitativeMinusNineAndZero()throws Exception {assertEquals(-9,PrsiceTables.finite("-9","quantitative phenotype"));assertEquals(0,PrsiceTables.finite("0e-999","zero"));}
    @Test void explicitLevelsOmitEmptyBinsAndRejectOutOfRangeSNP()throws Exception {var q=request();assertEquals(.01,PrsiceAudit.bin(q,.001).threshold());assertEquals(1,PrsiceAudit.bin(q,.1).threshold());direct(direct(q.get("parameters")).get("scoring")).put("thresholds",map("kind","LEVELS","levels",List.of(.01)));assertThrows(IOException.class,()->PrsiceAudit.bin(q,.1));}
    @Test void gridUsesOriginalCeilingAndFullCategory()throws Exception {var q=request();direct(direct(q.get("parameters")).get("scoring")).put("thresholds",map("kind","GRID","lower",.000001,"upper",.1,"interval",.01,"include_full",true));assertEquals(.010001,PrsiceAudit.bin(q,.005).threshold(),1e-16);assertEquals(1,PrsiceAudit.bin(q,.9).threshold());}
    @Test void gridOverflowNeverSilentlyChangesToGenericThresholds()throws Exception {var q=request();direct(direct(q.get("parameters")).get("scoring")).put("thresholds",map("kind","GRID","lower",0,"upper",1,"interval",1e-100,"include_full",false));assertThrows(PrsiceContracts.Unavailable.class,()->PrsiceAudit.bin(q,.1));}
    @Test void originalExportPrecisionIsEnforced()throws Exception {PrsiceAudit.rounded("0.123456789",.1234567891,9,"score");assertThrows(IOException.class,()->PrsiceAudit.rounded("0.12345678",.1234567891,9,"score"));}
    @Test void bedDecodingUsesBimA1Copies()throws Exception {Path bed=temporary.resolve("x.bed");Files.write(bed,new byte[]{0x6c,0x1b,1,(byte)0b11100100});try(var reader=new PrsiceGenotypes.Bed(bed,4,1)){byte[] b=reader.buffer();reader.row(0,b);assertArrayEquals(new int[]{2,-1,1,0},new int[]{PrsiceGenotypes.Bed.copies(b,0),PrsiceGenotypes.Bed.copies(b,1),PrsiceGenotypes.Bed.copies(b,2),PrsiceGenotypes.Bed.copies(b,3)});}}
    @Test void bedDimensionsAndModeCannotBeGuessed()throws Exception {Path bed=temporary.resolve("x.bed");Files.write(bed,new byte[]{0x6c,0x1b,1});assertThrows(IOException.class,()->new PrsiceGenotypes.Bed(bed,4,1));Files.write(bed,new byte[]{0x6c,0x1b,0,0});assertThrows(PrsiceContracts.Unavailable.class,()->new PrsiceGenotypes.Bed(bed,4,1));}
    @Test void savedProductCheckDoesNotMutateBytes()throws Exception {Path file=temporary.resolve("product.tsv");try(var p=new PrsiceAudit.Product(file,false)){p.row("FID","IID");p.row("F","literalß");}byte[] before=Files.readAllBytes(file);try(var p=new PrsiceAudit.Product(file,true)){p.row("FID","IID");p.row("F","literalß");}assertArrayEquals(before,Files.readAllBytes(file));assertThrows(IOException.class,()->{try(var p=new PrsiceAudit.Product(file,true)){p.row("changed");}});assertArrayEquals(before,Files.readAllBytes(file));}
    @Test void incompleteSavedEvidenceIsFailureRatherThanDependencySkip() {var sink=new PrintStream(OutputStream.nullOutputStream());assertEquals(2,PrsiceToolsCli.run(new String[]{"--inspect",temporary.toString()},sink,sink));try(var paths=assertDoesNotThrow(()->Files.list(temporary))){assertEquals(0,paths.count());}}
    @Test void existingOutputIsNeverClaimedByFailedRequest()throws Exception {var q=request();Path out=temporary.resolve("existing");Files.createDirectory(out);Files.writeString(out.resolve("unique"),"retain");q.put("out",out.toString());for(String name:List.of("base.tsv","target.bed","target.bim","target.fam"))Files.writeString(temporary.resolve(name),"preserve");Path f=temporary.resolve("request.json");ScenicWorkflowFiles.write(f,q);assertEquals(2,PrsiceToolsCli.run(new String[]{"--request",f.toString()},new PrintStream(OutputStream.nullOutputStream()),new PrintStream(OutputStream.nullOutputStream())));assertEquals("retain",Files.readString(out.resolve("unique")));try(var s=Files.list(out)){assertEquals(1,s.count());}}
    @Test void originalRuntimeResourcesHaveClosedSourceAndPlatformPins()throws Exception {var p=PrsiceRuntime.profile();assertEquals(47,object(p.get("source_files")).size());assertEquals(Set.of("windows","linux"),object(p.get("runtime_executables")).keySet());assertEquals("589ed823e9a84c56feb95ac58e7cf384626b9cbf4fda2a907bc36e103de1bad2",ScenicWorkflowFiles.sha(PrsiceRuntime.resource("LICENSE-upstream.txt")));}
}
